import{_ as t}from"./chunks/97922e77c3d19f61f9de.CPLfpGYK.js";import{_ as o,a}from"./chunks/920d83db104b71bb0c0d.aoSUT04O.js";import{_ as i,o as n,c as s,a6 as r}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"Life Lessons Learned From A Decade Of Failures","description":"","frontmatter":{"title":"Life Lessons Learned From A Decade Of Failures","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/life-lessons-learned-from-a-decade-of-failures.md","filePath":"en/letters/life-lessons-learned-from-a-decade-of-failures.md"}'),l={name:"en/letters/life-lessons-learned-from-a-decade-of-failures.md"};function h(m,e,p,d,u,f){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="life-lessons-learned-from-a-decade-of-failures" tabindex="-1">Life Lessons Learned From A Decade Of Failures <a class="header-anchor" href="#life-lessons-learned-from-a-decade-of-failures" aria-label="Permalink to &quot;Life Lessons Learned From A Decade Of Failures&quot;">​</a></h1><p>Dan Koe · 2021-11-11 · <a href="https://thedankoe.com/letters/life-lessons-learned-from-a-decade-of-failures/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/life-lessons-learned-from-a-decade-of-failures">返回中文译文</a></p><p>Over the past six months, my life has been a blur of breakthroughs, big ideas, and exponential progress. I’ve been experimenting with improvement in all areas of my life — mind, body, spirit, business — and after 10 years of life’s ebbs and flows… things are starting to come together.</p><p>When I first started lifting weights, I reached “The Peak Of Mount Stupid” within a year.</p><p><img src="'+t+'" alt=""></p><p>Dunning Kreugar Effect</p><p>I was obsessed with learning the fundamentals of training and nutrition. I studied people like Layne Norton, Alan Aragon, Eric Helms, and OG fitness influencers like Matt Ogus, Chris Lavado, Chris Jones, Vitruvian Physique, Michael Kory, and Rob Lipsett (<a href="https://open.spotify.com/episode/2LEFy0v4Hs18x5ZMT7BstX?si=f92bbfa7e3d44711&amp;utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">who I had the pleasure of doing a podcast with a few months ago</a>).</p><p>I became an IIFYM zealot. The only thing that mattered to me was calories and macros. I stuffed my face with frozen burritos, pop tarts, and anything I could get my hands on to hit my carbs, fats, and proteins.</p><p>This worked to an extent. I gained quite a bit of muscle and strength. I was repping 275lbs on the bench press in my senior year in high school — but quickly realized that overdosing on Dr. Pepper every night while playing Halo 3 until 3 AM wasn’t going to work. So I started experimenting.</p><h2 id="the-optimal-insert-aspect-of-life-here-is-a-myth" tabindex="-1">The Optimal (Insert Aspect Of Life Here) Is A Myth <a class="header-anchor" href="#the-optimal-insert-aspect-of-life-here-is-a-myth" aria-label="Permalink to &quot;The Optimal (Insert Aspect Of Life Here) Is A Myth&quot;">​</a></h2><p>Over the past 2 years, I have tried the vegan, keto, carnivore, low-carb, high-carb, and The Broke College Student diet.</p><p>Recently, I became dogmatic about the pseudo-carnivore diet. In a nutshell, you eat mainly organ meats, muscle meats, gelatinous parts of the animal, in-season fruits, eggs, dairy, and a few other things. Heavy emphasis on sourcing the highest quality you can find.</p><p>The reason I was so dogmatic is that I was on a spree of elimination. I dropped alcohol, social events, and anything else that took my away from hitting my goal of 185 pounds. I had been trying to hit that weight for 3-4 years and finally got fed up with my lack of progress. (<a href="https://open.spotify.com/episode/5Q8aAd1OKfKZT4mVhEVF85?si=833e193f4e0147a6&amp;utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">This podcast explains how my 25th birthday sparked this drastic change in mindset</a>).</p><p>Now that I have hit that goal, I am feeling myself moving from the “Slope Of Enlightenment” to the “Plateau Of Sustainability.”</p><p>Here are my recent realizations:</p><h2 id="balance-is-found-through-cycles-of-intensity" tabindex="-1">Balance Is Found Through Cycles Of Intensity <a class="header-anchor" href="#balance-is-found-through-cycles-of-intensity" aria-label="Permalink to &quot;Balance Is Found Through Cycles Of Intensity&quot;">​</a></h2><p>Hustle culture loves to glorify monk mode and intensity. I love a good old monk mode when you feel pulled to go all-in on a lesser purpose — laser-focused deep work, getting a years worth of work done in a month, losing sleep because the ideas won’t stop flowing, and riding the wave of dopamine &amp; intrinsic drive — but <em>sustainability</em> has to be taken into account.</p><p>If you stay in a state of intensity or optimization for too long, you hit a point of diminishing returns on quality of life.</p><p><img src="'+o+'" alt=""></p><p>When I started optimizing too much, <em>life lost its zest</em>. Things became stressful. Everything outside of my normal routine was seen as a burden. If I didn’t control every little thing about my life, I couldn’t enjoy it for what it is.</p><p><strong>Trying to perfect every area of your life makes you hate the imperfections.</strong> When you do this, you prevent yourself from enjoying the imperfection that is baked into the human condition.</p><p>Nature is perfect. Nature Is. Humans were blessed with thought. But thought overcomplicates and misinterprets nature as imperfect. Society models nature — over-optimizing this is not a way to live.</p><p>Going home for the holidays to see my family only made me think about what I could eat, how much money I was spending, and when I would be able to go back home to “get back on it.” I could imagine myself judging their “normie” actions. Not being able to enjoy time with my own family. When I head home later today, I will be making a conscious effort to enjoy my time with them.</p><p>However, these states of intensity and optimization are necessary. I wouldn’t have solidified these conclusions in my head without it. All self-improvement stems from awareness. Awareness is found by diving into the unknown. <em>You cannot improve what you are not aware of</em> — you cannot become aware of things you don’t know exist (they exist in the unknown… the uncomfortable… the realm of infinite potential).</p><p>When you transition out of these high-intensity states — you operate from a higher baseline on whatever you exponentially improved. Through intensity, you hit walls quickly. <em>You gain 1 year of experience in 1 month.</em> When you hit the metaphorical wall of over-optimization, life offers you a lesson. Are you going to learn from it?</p><h2 id="the-fundamentals-and-your-consistency-with-them-are-what-matters" tabindex="-1">The Fundamentals (And Your Consistency With Them) Are What Matters <a class="header-anchor" href="#the-fundamentals-and-your-consistency-with-them-are-what-matters" aria-label="Permalink to &quot;The Fundamentals (And Your Consistency With Them) Are What Matters&quot;">​</a></h2><p>Through my cycle of intensity, I have reached a higher baseline. I have better eating habits and my new fundamentals are locked down.</p><p>The fundamentals are what you can fall back on when things get too intense (or too lax). They are your system for getting results. They are the ‘levers’ for making progress.</p><p>When you feel lost, overwhelmed, or directionless in your pursuit of personal and business development, come back to the fundamentals — write them down.</p><p><strong>MY health fundamentals are now:</strong></p><ul><li>Daily raw liver, bone broth, and muscle meats for a pseudo-nose-to-tail carnivorous diet. Covering most bases in terms of vital nutrients.</li><li>Fruit, white rice, and tubers to fill carbs.</li><li>Fermented foods like goat milk kefir</li><li>My enlightenment elixir has and will remain a staple.</li><li>Full body training 3x a week</li><li>Running and sprinting 4x a week</li><li>Light activity (like hiking) on the weekend</li><li>Hitting 1 gram of protein per pound of bodyweight</li><li>Stress and emotional regulation</li></ul><p>Now that I am opening myself up to more social events, I am falling back to the 80/20 rule as I mentioned above. If I can stick to this for 80% of the time, it’s safe to say I will continue making exponential progress in health. Alcohol is still eliminated, for now, it caused too much trouble. However, I am having a good time experimenting with micro-dosing psilocybin (zero calories and a world of benefits when it comes to writing).</p><p>The thing that gets me is the body of “flexible dieters” that have sustainability in mind. Take it even further and you have someone like Timbahwolf on Instagram who eats like shit and has a better physique than 99% of social influencers.</p><p>The Rock eats pancakes. Michael Phelps smokes weed and eats a ton of pizza. What we see on Twitter is what we expose ourselves to. I completely forgot where I came from back in the day and may have attributed my progress poorly.</p><p><strong>From my reflection:</strong> the biggest impact on <em>my</em> mental clarity, skin, and energy levels is from not overeating, being lean, having a purpose, stress regulation, training, and movement. NOT necessarily the ultra-high-quality high-fat diet that many are promoting. <em>Most people stop overeating, start moving, stay consistent, and lockdown some other principles</em> — THEN they go on to say it was some magic like eating raw liver or going keto. It seems like the cause and effect that people talk about in the health industry are misidentified — or polarized to promote a product.</p><p>I am not saying this to sway your opinion. I’m saying this so you approach life critically. With an open mind. Not limiting what could lead to enjoyment because you limit your awareness and knowledge of <em>all areas</em> of one given field. I value critical thinking and nuance — I will be heading in that direction more instead of being so dogmatic about a specific way of eating.</p><p>Am I going to start gorging on junk food? No. I will test and experiment as you should. From this new baseline and level of awareness, I will be able to accurately see the short-term effects on my body.</p><p>When traveling, you bet your ass I’m not missing out on commonly demonized foods like pasta, bread, and other carb sources. I’ll probably post some pictures on <a href="https://instagram.com/thedankoe?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">Insta</a> of all the BBQ I’ll be eating in Texas next week. These are demonized by some researchers and glorified by others.</p><p>If you want to break out of whatever health ideology or religion you have subscribed to, <a href="https://open.spotify.com/episode/1G5UGm5BqnbAFoefA20zx1?si=Yjrk8KDZThqDY-y8yKWWhg&amp;utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">I’ve started listening to this older Joe Rogan podcast with Layne Norton and Dom D’Agostino</a> (they debate about flexible dieting and keto).</p><p>This is the beauty of these “Cycles Of Intensity.” My health philosophy is an amalgamation of the experience I’ve gained throughout my 10 years of improving it. It is backed by research and experience from all sides. This is powerful and is the same for other pillars of my life.</p><p>This does not eliminate the merit of a disciplined lifestyle. This IS a disciplined lifestyle. This “balanced” lifestyle is harder to pull off than eliminating things entirely — but with a higher potential reward. This is why intensity is needed to find balance. I spun my wheels for multiple years because I was afraid to go all in. I was afraid to learn the lessons that life had waiting for me in the unknown.</p><p>This is very different — yet very similar — compared to my previous diet. I got to this point through conscious experimentation.</p><h2 id="life-is-a-series-of-science-experiments" tabindex="-1"><strong>Life Is A Series Of Science Experiments</strong> <a class="header-anchor" href="#life-is-a-series-of-science-experiments" aria-label="Permalink to &quot;**Life Is A Series Of Science Experiments**&quot;">​</a></h2><p>I have been speaking in terms of health here… but this applies to all areas of life.</p><p><em>Every single topic can be argued and researched to the end of the Earth.</em> If I want to be dogmatic about holistic health, I can find research and compelling arguments backing that. There is no fun in that though. The fun comes from being open-minded, holding things in the realm of possibility, questioning everything, and solidifying a nuanced perspective through direct experience.</p><p>Life is about experimentation. Learning what you like and don’t like. Seeing what works and what doesn’t. Slowly making small upgrades in the traits, skills, and wisdom that your character holds. These small boosts in experience and upgrades lead to massive results in the game of life (sometimes you don’t even notice them until you reflect on your progress).</p><p>For me, I switched majors in college 6 times before I came across coding. That led to a dopamine-fueled extravaganza of learning to code. That led to experimenting with freelancing and other online business models. That led to starting Modern Mastery. The progress has been immense.</p><p>If you have no idea what to pursue — your life’s work, your purpose, your passions — <strong>you must start experimenting</strong>. You need to throw shit at a wall and see what sticks. <em>You need to try enough things until you experience that intrinsic drive that pulls you into a high-intensity state.</em> This happens thanks to dopamine. Dopamine separates signal from noise. Dopamine tells you that you are doing something right (beware: cheap dopamine).</p><p>How do you start experimenting? You treat all areas of your life as a science project.</p><p><img src="'+a+'" alt=""></p><p>The Scientific Method</p><p>Your body is a project. Your health is a project. Your relationships are a project. Your business is a project. All of these have more projects embedded in them. The “Project Mindset” is powerful. My roommate has started thinking of his body as a project. This simple act made him track his improvements, lose 80 pounds, and be mindful of how he “works” on this project.</p><p>Projects imply a desired outcome (improvement), steps to completion (goals and metrics), and actions that will move you closer to completion (priorities).</p><p>Experiments imply risks that you need to take into account, intention, testing, and iteration. This means that you have to see an experiment through. You can’t quit before things start to get good.</p><p>They also imply failure. Not all experiments are successful. When you think of this as a project, it is easier to detach from the outcome. You see failure as a chance to iterate and improve. Failure is feedback on what to improve. Looping back to awareness — <em>you cannot improve what you are not aware of.</em></p><p>You need to come into your experiments with an open and curious mind. This will give room for questioning. Curiosity is fueled by questions. Question: What would life look like if I tried this thing I’ve never tried before?</p><p>You will naturally feel the pull to dive into the unknown. If you don’t, keep asking questions until you feel energized. That is your call to adventure. A call to become an explorer of the unknown. A call to start actualizing your potential.</p><h2 id="the-meaning-of-life-is-to-pass-down-your-experiences" tabindex="-1"><strong>The Meaning Of Life Is To Pass Down Your Experiences</strong> <a class="header-anchor" href="#the-meaning-of-life-is-to-pass-down-your-experiences" aria-label="Permalink to &quot;**The Meaning Of Life Is To Pass Down Your Experiences**&quot;">​</a></h2><p>Experiments = experience.</p><p>Experimentation is how you find what works for you. Experimentation is how you form your personal health, wealth, and relationships philosophy — allowing you to pass down your lessons and make money doing so (this is arguably the meaning of life per ancient and modern teachers, self-transcendence).</p><p>Experimentation is how you form your life philosophy. An operating manual that keeps you on the enjoyable, sustainable, and fulfilling path.</p><p>Since we talk a lot about business here — this ties in perfectly. Business — in our case online business — is your vessel for pursuing your life’s work. Your life’s work consists of pursuing your interests (experiments), becoming a niche of one (understanding how to market, sell, and distribute), and packaging up your experiences in a way that the end-user can digest and implement. Money is a byproduct of your irreplaceable value.</p><p>If you enjoyed this blog post — you can get early access to all of them by subscribing to <a href="https://join.modernmastery.co/the-mastery-letter" target="_blank" rel="noreferrer">The Mastery Letter</a>.</p>',63)])])}const b=i(l,[["render",h]]);export{w as __pageData,b as default};
